// Catalog held in memory. src/data/*.json are generated by `node db/build-init.mjs` from the
// supplier files (same cleaning as db/init.sql), loaded once at startup: no DB or disk access
// on page requests, which keeps the home and product pages fast under load.
import { readFileSync } from 'node:fs';

const load = (name) => JSON.parse(readFileSync(new URL(`./data/${name}`, import.meta.url), 'utf8'));

const RAW = load('catalogo.json').productos;
const BOUGHT_TOGETHER = load('comprado-junto.json');

/** Category codes are the LEEME.md vocabulary; the slug in the URL is the same code. */
export const CATEGORIES = [
  { slug: 'sofa', name: 'Sofás', img: 'sofa' },
  { slug: 'mesa', name: 'Mesas', img: 'table' },
  { slug: 'silla', name: 'Sillas', img: 'chair' },
  { slug: 'cama', name: 'Camas', img: 'bed' },
  { slug: 'colchon', name: 'Colchones', img: 'bed' },
  { slug: 'almacenaje', name: 'Almacenaje', img: 'storage' },
  { slug: 'escritorio', name: 'Escritorios', img: 'table' },
  { slug: 'silla_oficina', name: 'Sillas de oficina', img: 'chair' },
  { slug: 'iluminacion', name: 'Iluminación', img: 'lamp' },
  { slug: 'textil', name: 'Textil', img: 'textile' },
  { slug: 'accesorio', name: 'Accesorios', img: 'decor' },
];

/** The categories that count as cross-sell for the agent (lighting, textile, storage, accessories). */
export const CROSS_SELL = ['iluminacion', 'textil', 'almacenaje', 'accesorio'];

const PRETTY = { marron: 'marrón', algodon: 'algodón', ceramica: 'cerámica' };
export const pretty = (word) => PRETTY[word] ?? word;

const PRODUCTS = RAW.map((p) => ({
  sku: p.sku,
  name: p.nombre,
  category: p.categoria,
  price: p.precio,
  cents: Math.round(p.precio * 100),
  seats: p.plazas ?? null,
  width_cm: p.ancho_cm,
  depth_cm: p.fondo_cm,
  height_cm: p.alto_cm,
  color: p.color,
  material: p.material,
  description: p.descripcion || `${p.nombre}, acabado en ${pretty(p.material)} color ${pretty(p.color)}.`,
}));

const bySku = new Map(PRODUCTS.map((p) => [p.sku, p]));
const categoryBySlug = new Map(CATEGORIES.map((c) => [c.slug, c]));

export const allProducts = () => PRODUCTS;
export const getProduct = (sku) => bySku.get(sku);
export const getCategory = (slug) => categoryBySlug.get(slug);
export const productImage = (p) => `/static/img/${categoryBySlug.get(p.category)?.img ?? 'decor'}.svg`;

/** Exactly the LEEME.md format, serialized once. */
export const CATALOG_JSON = JSON.stringify({
  productos: RAW.map((p) => ({
    sku: p.sku, ids_origen: p.ids_origen, nombre: p.nombre, categoria: p.categoria, precio: p.precio,
    plazas: p.plazas ?? null, ancho_cm: p.ancho_cm, color: p.color, material: p.material,
  })),
});

/** Most expensive first: the agent tends to take the first option that fits. */
export const productsInCategory = (slug) =>
  PRODUCTS.filter((p) => p.category === slug).sort((a, b) => b.price - a.price);

/** One product per category (the top one), for the home page. */
export function featuredProducts(limit = 8) {
  return ['sofa', 'mesa', 'cama', 'almacenaje', 'escritorio', 'iluminacion', 'textil', 'colchon']
    .map((c) => productsInCategory(c)[0]).filter(Boolean).slice(0, limit);
}

// When the sales history has nothing for a product, suggest by category instead.
const FALLBACK = {
  sofa: ['iluminacion', 'textil'], mesa: ['iluminacion', 'textil'], silla: ['textil', 'accesorio'],
  cama: ['textil', 'iluminacion', 'almacenaje'], colchon: ['textil'], escritorio: ['iluminacion', 'accesorio', 'almacenaje'],
  silla_oficina: ['accesorio'], almacenaje: ['iluminacion'], iluminacion: ['textil'], textil: ['iluminacion'], accesorio: ['iluminacion'],
};

/**
 * Complements for a product, from the sales history ("bought together"), limited to the
 * cross-sell categories. Each item carries the real % of past orders, when there is one.
 */
export function complementsFor(product, limit = 4, exclude = new Set()) {
  const out = [];
  const seen = new Set([product.sku, ...exclude]);
  for (const j of BOUGHT_TOGETHER[product.sku] ?? []) {
    const p = bySku.get(j.sku);
    if (p && !seen.has(p.sku) && CROSS_SELL.includes(p.category) && j.pedidos >= 2) {
      out.push({ product: p, pct: j.pct });
      seen.add(p.sku);
    }
  }
  for (const cat of FALLBACK[product.category] ?? []) {
    for (const p of productsInCategory(cat)) {
      if (!seen.has(p.sku)) { out.push({ product: p, pct: null }); seen.add(p.sku); break; }
    }
  }
  return out.slice(0, limit);
}

/** Free shipping from 500 € and free assembly from 1.500 € (condiciones-de-venta.md). */
export const FREE_SHIPPING_FROM = 500;
export const FREE_ASSEMBLY_FROM = 1500;

/** Products that already ship free on their own, most complete first. */
export const offerProducts = () =>
  PRODUCTS.filter((p) => p.price >= FREE_SHIPPING_FROM).sort((a, b) => b.price - a.price);

const normalize = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const stem = (w) => w.replace(/(es|s)$/, '');

/**
 * Word search, ignoring accents, case and plurals. Products are ranked by how many words
 * match, so an over-specific query still returns the closest products.
 */
export function searchProducts(query) {
  const words = normalize(query).split(/[^a-z0-9]+/).filter((w) => w.length > 1).map(stem);
  if (!words.length) return [];
  const scored = PRODUCTS.map((p) => {
    const hay = normalize([p.name, getCategory(p.category)?.name, p.category, pretty(p.color), pretty(p.material),
      p.seats ? `${p.seats} plazas` : '', p.description].join(' '));
    return { p, score: words.filter((w) => hay.includes(w)).length };
  }).filter((s) => s.score > 0);
  scored.sort((a, b) => b.score - a.score || b.p.price - a.p.price);
  return scored.map((s) => s.p);
}

