function expandPack(pack) {
  const lines = pack.items.map(([sku, quantity]) => ({ product: bySku.get(sku), quantity }));
  if (lines.some((l) => !l.product)) throw new Error(`pack ${pack.id} references an unknown sku`);
  const totalCents = lines.reduce((s, l) => s + l.quantity * l.product.cents, 0);
  return { ...pack, lines, total: totalCents / 100 };
}

const EXPANDED_PACKS = PACKS.map(expandPack);
export const getPacks = () => EXPANDED_PACKS;
export const getPack = (id) => EXPANDED_PACKS.find((p) => p.id === id);
